/* V9.4 high-value semantic and workflow regression tests. */
'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs');
const crypto = require('node:crypto');
const C = require('./src/v6-core.js');
const P = require('./src/v6-projection.js');
const F = require('./src/v7-framework.js');
const R = require('./src/v8-read.js');
const Access = require('./src/v9-access.js');
const Model = require('./src/v9-model.js');
const V93Model = require('./src/demo-model.js');
const D = require('./src/decision.js');
const Reading = require('./src/knowledge-reading.js');
const Task = require('./src/task.js');
const AKP = require('./src/v9-akp.js');
const W = require('./src/write-access.js');
const demo = require('./fixtures/demo-projects.js');
const results = [];
const clone = value => JSON.parse(JSON.stringify(value));
const digest = value => crypto.createHash('sha256').update(JSON.stringify(value)).digest('hex');
function test(name, fn) { try { fn(); results.push({ name, status: 'PASS' }); console.log(`✓ ${name}`); } catch (error) { results.push({ name, status: 'FAIL', error: error.message }); console.error(`✗ ${name}\n  ${error.message}`); } }
function ctx(project, role = 'owner') { return R.context(project, { versionMode: 'published', baselineId: project.versionLayers.baseline, permissionContext: { role, clearance: role === 'external' ? 'public' : 'restricted' }, applicableContext: { environment: 'production', organization: '华东一厂', configurationVersion: 'CFG-M-2026.11', asOf: '2026-11-16' } }); }
function fresh(id = 'PRJ-00003') { const project = clone(demo[id]); C.initProject(project); F.initProject(project); Model.initProject(project); V93Model.initProject(project); return project; }
function newCandidate(project) {
  const created = Task.createChangeTask(project, ctx(project, 'developer'), { rootId: 'FEAT-M02', description: '避免旧批次版本覆盖新异常登记', targetBehavior: '既有条件成立且预期版本匹配时才允许登记', taskType: 'business-rule-change' });
  assert(created.ok, created.errors?.join('；'));
  const proposed = Task.proposeDecisionChange(project, ctx(project, 'developer'), created.task.id, { ruleId: 'RULE-M002', rowId: 'MR2-03', condition: { op: 'equals', inputId: 'expectedVersionMatch', value: true }, inputSemantics: { label: '预期批次版本是否匹配', businessMeaning: '请求预期版本必须与当前批次版本一致', kind: 'boolean' }, outcomeId: 'REGISTER', naturalLanguage: '生产中、依据完整且预期版本匹配时才允许登记' });
  assert(proposed.ok, proposed.errors?.join('；'));
  return { task: created.task, proposal: proposed.change };
}
function replaceEntity(project, entity) { project.publishedEntities[entity.id] = entity; project.knowledgeRevisions[`${entity.id}@${entity.revision}`] = entity; }

test('规则正例、反例和未知输入均由真实条件计算', () => { const p = fresh(), c = ctx(p); assert.equal(D.evaluateRule(p, c, 'RULE-M002', { batchState: '生产中', evidence: 'complete' }).outcome.id, 'REGISTER'); assert.equal(D.evaluateRule(p, c, 'RULE-M002', { batchState: '已放行', evidence: 'complete' }).outcome.id, 'REJECT'); assert.equal(D.evaluateRule(p, c, 'RULE-M002', { batchState: '生产中' }).code, 'MISSING_INPUT'); });
test('未确认优先级和未批准规则不会形成确定业务结论', () => { const p = C.createBlankProject('PRJ-T94-RULE', '规则边界', 'test'); Model.initProject(p); V93Model.initProject(p); const definition = { scope: 'test', supportsEvaluation: true, inputs: [{ id: 'x', label: '输入' }], outcomes: [{ id: 'A', label: 'A' }, { id: 'B', label: 'B' }], rows: [{ id: '1', priority: 10, when: { x: 'x' }, outcomeId: 'A' }, { id: '2', priority: 10, when: { x: 'x' }, outcomeId: 'B' }], exceptions: [], priorityPolicy: { strategy: 'explicit', confirmed: true } }; C.execute(p, 'DefineRule', { entityId: 'RULE-T94', name: '冲突规则', scope: 'test', definition }, W.SYSTEM_CONTEXT); assert(C.proposeChange(p, { reason: 'fixture', context: W.SYSTEM_CONTEXT }).ok); assert(C.publishRevision(p, { confirmedBy: 'owner', context: W.SYSTEM_CONTEXT }).ok); assert.equal(D.evaluateRule(p, ctx(p), 'RULE-T94', { x: 'x' }).code, 'RULE_CONFLICT'); const draft = C.createBlankProject('PRJ-T94-DRAFT', 'draft', 'draft'); Model.initProject(draft); V93Model.initProject(draft); C.execute(draft, 'DefineRule', { entityId: 'RULE-DRAFT', name: 'draft', scope: 'draft', definition }, W.SYSTEM_CONTEXT); assert.equal(D.evaluateRule(draft, R.context(draft, { versionMode: 'draft', permissionContext: { role: 'reader', clearance: 'restricted' } }), 'RULE-DRAFT', { x: 'x' }).code, 'UNAPPROVED_TARGET'); });
test('历史基线保持不变且历史规则不被新修订污染', () => { const p = fresh(), oldBaseline = p.versionLayers.baseline, before = digest(p.baselines); C.execute(p, 'SetProperty', { entityId: 'RULE-M002', path: 'description', value: '新说明' }, ctx(p)); assert(C.proposeChange(p, { reason: 'test history', context: ctx(p) }).ok); assert(C.publishRevision(p, { confirmedBy: 'owner', context: ctx(p) }).ok); assert.equal(digest(p.baselines.slice(0, -1)), digest(fresh().baselines)); assert.equal(before, digest(fresh().baselines)); assert(C.baselineById(p, oldBaseline)); });
test('七阶段 Flow 的节点、条件、回流和规则引用完整', () => { const p = fresh(), view = Reading.decisionProjection(p, ctx(p), 'SCN-M001'), flow = view.flows[0]; assert.equal(flow.stages.length, 7); assert.equal(flow.edges.length, 14); assert(flow.edges.some(edge => edge.type === 'return' && edge.when.outcomeId === 'REWORK')); assert(view.targetRules.some(rule => rule.entity.id === 'RULE-M001')); });
test('有效绑定的目标、观察、代码、环境和证据支持一致结论', () => { const p = fresh(), conformance = Reading.decisionProjection(p, ctx(p), 'FEAT-M02').conformance; assert.equal(conformance.status, 'consistent', conformance.explanation); });
test('代码版本变化使旧符合性自动失效', () => { const p = fresh(); p.versionLayers.codeRevision = 'commit-new'; assert.equal(Reading.decisionProjection(p, ctx(p), 'FEAT-M02').conformance.code, 'CODE_VERSION_CHANGED'); });
test('目标规则修订变化使符合性待复核', () => { const p = fresh(), observation = clone(C.getEntity(p, 'OBS-M-REGISTER', { baselineId: p.versionLayers.baseline })); observation.props.conformance.targetRuleRevision = 'old-rule-revision'; replaceEntity(p, observation); assert.equal(Reading.decisionProjection(p, ctx(p), 'FEAT-M02').conformance.code, 'TARGET_REVISION_CHANGED'); });
test('观察修订变化使符合性待复核', () => { const p = fresh(), observation = clone(C.getEntity(p, 'OBS-M-REGISTER', { baselineId: p.versionLayers.baseline })); observation.revision = 'r2'; replaceEntity(p, observation); C.baselineById(p, p.versionLayers.baseline).entries[observation.id] = 'r2'; assert.equal(Reading.decisionProjection(p, ctx(p), 'FEAT-M02').conformance.code, 'OBSERVATION_REVISION_CHANGED'); });
test('证据修订变化使符合性待复核', () => { const p = fresh(), source = clone(C.getEntity(p, 'SRC-M03', { baselineId: p.versionLayers.baseline })); source.revision = 'r2'; replaceEntity(p, source); C.baselineById(p, p.versionLayers.baseline).entries[source.id] = 'r2'; assert.equal(Reading.decisionProjection(p, ctx(p), 'FEAT-M02').conformance.code, 'EVIDENCE_REVISION_CHANGED'); });
test('缺少完整版本绑定的旧标签不能继续宣称一致', () => { const p = fresh(), observation = clone(C.getEntity(p, 'OBS-M-REGISTER', { baselineId: p.versionLayers.baseline })); delete observation.props.conformance.observationRevision; replaceEntity(p, observation); assert.equal(Reading.decisionProjection(p, ctx(p), 'FEAT-M02').conformance.code, 'CONFORMANCE_BINDING_MISSING'); });
test('只读角色不能创建 Task 或候选决定', () => { const p = fresh(); assert.throws(() => Task.createChangeTask(p, ctx(p, 'reader'), { description: '只读创建' }), /WRITE_FORBIDDEN|无权/); const candidate = newCandidate(p); assert.throws(() => Task.proposeDecisionChange(p, ctx(p, 'reader'), candidate.task.id, { ruleId: 'RULE-M002', rowId: 'MR2-03' }), /无权/); });
test('信息不足只创建待澄清需求且不生成空影响审计表', () => { const p = fresh(), result = Task.createChangeTask(p, ctx(p, 'developer'), { description: '用户只描述了一个问题' }); assert(result.ok); assert.equal(result.task.deliveryState, 'clarification-required'); assert.equal(result.task.rootId, null); assert.equal(result.task.impactInvestigation.items.length, 0); });
test('开发可提出候选，但批准前不创建知识草稿', () => { const p = fresh(), candidate = newCandidate(p); assert.equal(candidate.proposal.approvalStatus, 'proposed'); assert.equal(p.draftWorkspace, null); assert(p.decisionRecords.some(record => record.decisionId === candidate.proposal.proposalId && !record.approval)); });
test('Owner 批准后形成真实 DefineRule 草稿而非状态字符串', () => { const p = fresh(), candidate = newCandidate(p), result = Task.decideBusinessChange(p, ctx(p, 'owner'), candidate.task.id, candidate.proposal.proposalId, { decision: 'approved', by: '业务 Owner', rationale: '并发保护需要' }); assert(result.ok && result.draftCreated); assert.equal(p.draftWorkspace.status, 'draft'); const rule = C.getEntity(p, 'RULE-M002', { draft: true }); assert.equal(rule.currentVersion, 'draft'); assert(p.draftWorkspace.deliveryLinks.some(link => link.proposalId === candidate.proposal.proposalId)); });
test('拒绝候选不创建知识草稿且不能按已变更验收', () => { const p = fresh(), candidate = newCandidate(p), result = Task.decideBusinessChange(p, ctx(p, 'owner'), candidate.task.id, candidate.proposal.proposalId, { decision: 'rejected', by: '业务 Owner', rationale: '保持原规范' }); assert(result.ok && !result.draftCreated); assert.equal(p.draftWorkspace, null); assert(Task.evaluateDelivery(p, ctx(p), candidate.task.id).blockers.some(item => item.code === 'BUSINESS_DECISION_REJECTED')); });
test('非 Owner 不能提交或发布基线', () => { const p = fresh(), candidate = newCandidate(p); Task.decideBusinessChange(p, ctx(p, 'owner'), candidate.task.id, candidate.proposal.proposalId, { decision: 'approved', by: '业务 Owner', rationale: 'test' }); assert.throws(() => C.execute(p, 'ProposeChange', { reason: 'test' }, ctx(p, 'developer')), /无权/); assert.throws(() => C.execute(p, 'PublishRevision', { confirmedBy: 'fake' }, ctx(p, 'editor')), /无权/); });
test('发布会更新知识、Manifest 和 Task 状态而不修改旧基线', () => { const p = fresh(), candidate = newCandidate(p), oldBaseline = p.versionLayers.baseline; Task.decideBusinessChange(p, ctx(p, 'owner'), candidate.task.id, candidate.proposal.proposalId, { decision: 'approved', by: '业务 Owner', rationale: 'test' }); assert(C.execute(p, 'ProposeChange', { reason: 'approved change' }, ctx(p)).ok); const published = C.execute(p, 'PublishRevision', { confirmedBy: '业务 Owner' }, ctx(p)); assert(published.ok, published.errors?.join('；')); const task = p.tasks.find(item => item.id === candidate.task.id); assert.equal(task.delivery.knowledgeChanges[0].status, 'approved'); assert.equal(task.delivery.deliveryManifest.approvedBaselineId, published.baseline.id); assert.equal(task.deliveryState, 'knowledge-approved-contract-review-required'); assert(C.baselineById(p, oldBaseline)); });
test('模拟交付经契约复核和人工影响确认后可完成内部验收', () => { const p = fresh(), candidate = newCandidate(p), developer = ctx(p, 'developer'), owner = ctx(p, 'owner'); for (const item of candidate.task.impactInvestigation.items) Task.recordImpactDecision(p, developer, candidate.task.id, item.id, { status: item.status === 'required' ? 'required' : 'no-change', completion: item.status === 'required' ? 'done' : 'checked', rationale: item.status === 'required' ? '模拟实现和测试已覆盖' : '已检查现有关系，无需修改' }); Task.recordLegacyPathReview(p, developer, candidate.task.id, { rationale: '人工检查现有调用与兼容记录，未执行真实仓库调查' }); Task.attachSimulatedDelivery(p, developer, candidate.task.id, { codeRevision: 'commit-sim-94', testCommand: '模拟正反边界回归', deploymentVersion: 'deploy-sim-94' }); Task.decideBusinessChange(p, owner, candidate.task.id, candidate.proposal.proposalId, { decision: 'approved', by: '业务 Owner', rationale: 'test' }); assert(C.execute(p, 'ProposeChange', { reason: 'approved change' }, owner).ok); assert(C.execute(p, 'PublishRevision', { confirmedBy: '业务 Owner' }, owner).ok); const task = p.tasks.find(item => item.id === candidate.task.id), review = P.reviewTask(p, task.id, { context: owner, permission: owner.permissionContext }); assert(review.ok, review.errors?.join('；')); const completed = Task.completeTask(p, owner, task.id, { by: '验收 Owner', evidence: '模拟内部验收' }); assert(completed.ok, completed.errors?.join('；')); assert.equal(task.deliveryState, 'fully-delivered'); });
test('项目保存重开后知识、Task 与旧 VisualView 数据仍可恢复', () => { const p = fresh(); p.visualViews.push({ viewId: 'OLD-VIEW', rootKnowledgeId: 'FEAT-M02', title: '历史注释', annotationRefs: ['SRC-M02'], layout: { x: 99, zoom: 2 } }); const restored = JSON.parse(JSON.stringify(p)); assert(restored.visualViews.some(view => view.viewId === 'OLD-VIEW' && view.annotationRefs.length)); assert(restored.tasks.some(task => task.id === 'TASK-M93-DELIVERY')); assert(restored.publishedEntities['RULE-M002']); });
test('完整 AKP 仅在显式导入时写入草稿', () => { const p = C.createBlankProject('PRJ-T94-AKP', 'AKP', 'AKP'); Model.initProject(p); V93Model.initProject(p); const pack = JSON.parse(fs.readFileSync('packages/business-atlas-self.akp.json', 'utf8')), staged = AKP.stagePackage(p, pack, { context: ctx(p, 'developer') }); assert(staged.ok, staged.validation.errors.join('；')); const committed = AKP.commitImport(p, staged.proposal.proposalId, { context: ctx(p, 'developer') }); assert(committed.ok, committed.errors?.join('；')); assert(p.draftWorkspace); assert(Object.keys(p.draftWorkspace.entities).length > 0); });
test('构建无绘图运行、无 Self 快照且体积和模块数显著下降', () => { const html = fs.readFileSync('dist/business-atlas-v9.4.html', 'utf8'), build = JSON.parse(fs.readFileSync('artifacts/v9-4-build.json', 'utf8')); assert(!/<svg\b|<canvas\b|localDiagram|detailedFlowGraph|stageGraph|stateGraph/i.test(html)); assert(!html.includes('src/v9-self-project.js')); assert(build.scripts.length <= 21); assert(Buffer.byteLength(html) < 1024 * 1024); });

const failed = results.filter(result => result.status === 'FAIL');
console.log(`\n${results.length - failed.length}/${results.length} 项 V9.4 核心测试通过。`);
fs.mkdirSync('artifacts', { recursive: true }); fs.writeFileSync('artifacts/v9-4-test-results.json', JSON.stringify({ generatedAt: new Date().toISOString(), passed: results.length - failed.length, total: results.length, results }, null, 2));
if (failed.length) process.exitCode = 1;
